            } catch (error) {
                console.error("Error fetching background image:", error);
            }
        }

        fetchData();
    }, []);

    return (
        <Box
            display="flex"
            justifyContent="center"
            alignItems="center"
            height="100vh"
            width="100%"
            style={{
                position: "relative",
                backgroundImage: `url(${backImage})`,
                backgroundSize: "cover",
                backgroundPosition: "center",
            }}
        >
            <Box
                bgcolor="rgba(255, 255, 255, 0.8)"
                borderRadius="8px"
                padding="40px"
                boxShadow="0 4px 6px rgba(0, 0, 0, 0.1)"
                textAlign="center"
                width="90%"
                maxWidth="400px"
                style={{
                    backdropFilter: "blur(10px)",
                    WebkitBackdropFilter: "blur(10px)",
                    zIndex: 1,
                }}
            >
                <Typography fontWeight="bold" fontSize="25px" mb="30px">
                    VSpaceへログイン
                </Typography>
                <TextField
                    id="email"
                    label="Email"
                    variant="outlined"
                    fullWidth
                    style={{ marginBottom: "15px" }}
                />
                <TextField
                    id="password"
                    label="Password"
                    variant="outlined"
                    fullWidth
                    style={{ marginBottom: "15px" }}
                    type="password"
                />
                <FormGroup style={{ marginBottom: "15px" }}>
                    <FormControlLabel
                        control={<Checkbox />}
                        label="自動ログイン"
                    />
                </FormGroup>
                <Button
                    variant="contained"
                    fullWidth
                    style={{ padding: "15px", backgroundColor: "black" }}
                >
                    ログイン
                </Button>
            </Box>
        </Box>
    )
}
